// ============================================================================
// HTTP SECURITY HEADERS
// ============================================================================
export const HTTP_SECURITY_HEADERS = [
  { header: "Content-Security-Policy", abbr: "CSP", desc: "Controls which resources the browser can load for this page", importance: "critical", example: "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data:; frame-ancestors 'none'", security: "Primary defense against XSS. Restricts script sources, inline scripts, eval, and frame embedding. Use nonce or hash for inline scripts instead of 'unsafe-inline'." },
  { header: "Strict-Transport-Security", abbr: "HSTS", desc: "Forces HTTPS connections for the specified duration", importance: "critical", example: "max-age=31536000; includeSubDomains; preload", security: "Prevents SSL stripping attacks. max-age should be at least 1 year (31536000). includeSubDomains protects all subdomains. 'preload' submits to browser preload lists for first-visit protection." },
  { header: "X-Content-Type-Options", desc: "Prevents MIME-type sniffing", importance: "high", example: "nosniff", security: "Prevents browsers from interpreting files as a different MIME type than declared. Blocks attacks where a server serves user content with wrong Content-Type (e.g., HTML masquerading as image)." },
  { header: "X-Frame-Options", desc: "Controls whether the page can be embedded in frames", importance: "high", example: "DENY", security: "Prevents clickjacking by disabling iframe embedding. DENY blocks all framing, SAMEORIGIN allows same-origin only. Superseded by CSP frame-ancestors but still needed for older browsers." },
  { header: "Referrer-Policy", desc: "Controls how much referrer information is sent", importance: "medium", example: "strict-origin-when-cross-origin", security: "Prevents leaking sensitive URL paths/query parameters to external sites. 'no-referrer' sends nothing, 'strict-origin-when-cross-origin' sends only origin for cross-origin HTTPS requests." },
  { header: "Permissions-Policy", desc: "Controls which browser features the page can use", importance: "medium", example: "camera=(), microphone=(), geolocation=(), payment=()", security: "Disables powerful features like camera, microphone, geolocation, and payment APIs unless explicitly needed. Replaces the older Feature-Policy header." },
  { header: "Cross-Origin-Opener-Policy", abbr: "COOP", desc: "Isolates the browsing context from cross-origin openers", importance: "medium", example: "same-origin", security: "Prevents Spectre-like side-channel attacks by isolating the process. 'same-origin' ensures window.opener is null for cross-origin pages." },
  { header: "Cross-Origin-Embedder-Policy", abbr: "COEP", desc: "Prevents loading cross-origin resources without CORS", importance: "medium", example: "require-corp", security: "Together with COOP, enables SharedArrayBuffer and high-resolution timers safely. Blocks non-CORS cross-origin resources." },
  { header: "Cross-Origin-Resource-Policy", abbr: "CORP", desc: "Controls which origins can load this resource", importance: "medium", example: "same-origin", security: "Prevents cross-origin reads of the resource (Spectre mitigation). 'same-origin' blocks all cross-origin reads, 'cross-origin' allows them." },
  { header: "X-XSS-Protection", desc: "Legacy XSS filter (mostly disabled now)", importance: "low", example: "0", security: "Deprecated — the XSS filter itself could be exploited. Set to 0 to disable. CSP is the modern replacement. Chrome removed their XSS Auditor in 2019." },
  { header: "Cache-Control", desc: "Controls caching behavior", importance: "high", example: "no-store, no-cache, must-revalidate, private", security: "Sensitive pages should use 'no-store' to prevent caching of auth tokens, personal data. 'private' prevents CDN/proxy caching. 'no-cache' requires revalidation." },
  { header: "Set-Cookie", desc: "Sets HTTP cookies", importance: "critical", example: "session=abc123; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=3600", security: "Secure: HTTPS only. HttpOnly: no JavaScript access (XSS protection). SameSite=Strict: no cross-site requests. SameSite=Lax: allows top-level navigations. Path=/ limits scope." },
  { header: "Access-Control-Allow-Origin", abbr: "CORS", desc: "Specifies which origins can access the response", importance: "high", example: "https://darknode.ai", security: "Never use * with credentials. Reflecting the Origin header without validation is equivalent to * and bypasses SOP. Validate against an allowlist of trusted origins." },
  { header: "Content-Type", desc: "Specifies the media type of the response body", importance: "high", example: "application/json; charset=utf-8", security: "Always set charset to prevent charset-sniffing XSS. Use application/json (not text/html) for API responses. Combined with X-Content-Type-Options: nosniff for full protection." },
  { header: "X-DNS-Prefetch-Control", desc: "Controls DNS prefetching", importance: "low", example: "off", security: "DNS prefetching can leak which links are on a page. Set to 'off' for privacy-sensitive pages (webmail, banking)." },
];

